from zkregion import *
P = 100003
def prover(secret, prime=P, gen=3):
    return SchnorrProver(secret, prime=prime, generator=gen, randbelow=lambda n: 7)
alice = prover(4321); bob = prover(7777); carol = prover(5566, prime=104723)
def mentry(p, msg, prime=P, gen=3):
    return MultiSchnorrEntry(p.public_key, msg, p.prove(msg, context=b"ctx"), b"ctx", prime, gen)
def counter():
    x = 0
    def r(n):
        nonlocal x
        x += 1
        return x % n
    return r
for size in range(1, 6):
    src = [alice, bob, carol, alice, bob][:size]
    entries = [mentry(p, f"m{i}".encode()) for i, p in enumerate(src)]
    ok = verify_schnorr_batch(entries, randbelow=counter())
    print(size, ok)
